export function getLocalizedCateringItem(item: CateringItem, lang: string): CateringItem {
  if (lang !== 'es') return item;

  const translated = CATERING_TRANSLATIONS_ES[item.id] || CATERING_TRANSLATIONS_ES[item.name];
  if (translated) {
    return {
      ...item,
      name: translated.name,
      description: translated.desc || item.description,
    };
  }

  return item;
}
